"extends SceneTree

func _init() -> void:
	var script = load("res://../../STUDIO_V3/evidence/V3-002-R2/live_workflow/fixture_stamina_component.gd")
	var comp = script.new()

	var dep_count = [0]
	comp.stamina_depleted.connect(func(): dep_count[0] += 1)

	comp.init(100.0)
	print("initial: ", comp.current_stamina)
	var r1 = comp.consume_stamina(40.0)
	print("after 40: ", comp.current_stamina, " r1=", r1, " dep=", dep_count[0])
	var r2 = comp.consume_stamina(60.0)
	print("after 60: ", comp.current_stamina, " r2=", r2, " dep=", dep_count[0])
	quit(0)
"
